with flattened as (select id, host, level, latency_ms, key, v from app_logs lateral view outer explode(context) e as key, v) select *, round(latency_ms / sum(latency_ms) over (partition by host), 4) latency_ms_share, rank() over (order by latency_ms nulls last) latency_ms_rank, max(latency_ms) over (partition by host) host_max_latency_ms, rank() over (order by latency_ms desc nulls last) latency_ms_rank_2, sum(latency_ms) over (partition by key, level) key_sum_latency_ms from flattened;
